        Lesson(id = 2, moduleId = 1, titleEn = "Derivatives", titleKn = "ಉತ್ಪನ್ನಗಳು", contentEn = "The derivative measures the instantaneous rate of change of a function. It is defined as f'(x) = lim(h→0) [f(x+h) - f(x)] / h. This limit, when it exists, gives us the slope of the tangent line at any point.\n\nCommon differentiation rules include the power rule (d/dx xⁿ = nxⁿ⁻¹), product rule, quotient rule, and chain rule. These rules allow us to differentiate complex functions systematically.\n\nApplications of derivatives include finding maximum and minimum values, determining rates of change in physics and engineering, and linear approximation.", contentKn = "ಉತ್ಪನ್ನವು ಕಾರ್ಯದ ತಕ್ಷಣದ ಬದಲಾವಣೆಯ ದರವನ್ನು ಅಳೆಯುತ್ತದೆ.", keyPointsEn = "• Definition: f'(x) = lim(h→0) [f(x+h) - f(x)] / h\n• Power rule, product rule, chain rule\n• Applications: max/min, rates of change\n• Second derivative and concavity", keyPointsKn = "• ವ್ಯಾಖ್ಯಾನ: f'(x)\n• ಶಕ್ತಿ ನಿಯಮ, ಉತ್ಪನ್ನ ನಿಯಮ\n• ಅನ್ವಯಗಳು: ಗರಿಷ್ಠ/ಕನಿಷ್ಠ", orderIndex = 2),
        Lesson(id = 3, moduleId = 1, titleEn = "Integration", titleKn = "ಸಮಾಕಲನ", contentEn = "Integration is the reverse process of differentiation. The indefinite integral ∫f(x)dx represents the family of antiderivatives of f(x). The Fundamental Theorem of Calculus connects differentiation and integration.\n\nCommon techniques include substitution, integration by parts, partial fractions, and trigonometric substitution. The definite integral ∫[a,b] f(x)dx gives the signed area under the curve.\n\nApplications include computing areas, volumes of revolution, work done by forces, and probability distributions in statistics.", contentKn = "ಸಮಾಕಲನವು ವ್ಯತ್ಯಾಸದ ಹಿಮ್ಮುಖ ಪ್ರಕ್ರಿಯೆ.", keyPointsEn = "• Fundamental Theorem of Calculus\n• Techniques: substitution, by parts, partial fractions\n• Definite vs indefinite integrals\n• Applications: area, volume, work", keyPointsKn = "• ಕಲನಶಾಸ್ತ್ರದ ಮೂಲಭೂತ ಪ್ರಮೇಯ\n• ತಂತ್ರಗಳು: ಪ್ರತಿಕ್ಷೇಪಣೆ\n• ನಿರ್ದಿಷ್ಟ ಮತ್ತು ಅನಿರ್ದಿಷ್ಟ ಸಮಾಕಲನ", orderIndex = 3),

