        Lesson(id = 5, moduleId = 2, titleEn = "Eigenvalues and Eigenvectors", titleKn = "ಐಗೆನ್ ಮೌಲ್ಯಗಳು ಮತ್ತು ಐಗೆನ್ ವೆಕ್ಟರ್‌ಗಳು", contentEn = "An eigenvector of a matrix A is a non-zero vector v such that Av = λv, where λ is the eigenvalue. Finding eigenvalues involves solving det(A - λI) = 0, known as the characteristic equation.\n\nEigenvalues reveal important properties of linear transformations: they tell us about stretching, compression, and rotation. In engineering, eigenvalue analysis is used in vibration analysis, stability of structures, and principal component analysis.\n\nDiagonalization of matrices using eigenvectors simplifies matrix powers and exponentials, which are essential in solving systems of differential equations.", contentKn = "ಮ್ಯಾಟ್ರಿಕ್ಸ್ A ಯ ಐಗೆನ್‌ವೆಕ್ಟರ್ ಒಂದು ಶೂನ್ಯೇತರ ವೆಕ್ಟರ್ v ಆಗಿದ್ದು Av = λv.", keyPointsEn = "• Eigenvalue equation: Av = λv\n• Characteristic equation: det(A - λI) = 0\n• Diagonalization: A = PDP⁻¹\n• Applications in engineering", keyPointsKn = "• ಐಗೆನ್ ಮೌಲ್ಯ ಸಮೀಕರಣ\n• ಗುಣಲಕ್ಷಣ ಸಮೀಕರಣ\n• ಕರ್ಣೀಕರಣ", orderIndex = 2),

        // Data Structures lessons
        Lesson(id = 6, moduleId = 3, titleEn = "Arrays and Linked Lists", titleKn = "ಸರಣಿಗಳು ಮತ್ತು ಲಿಂಕ್ಡ್ ಪಟ್ಟಿಗಳು", contentEn = "Arrays are contiguous memory blocks where elements are stored sequentially and accessed using indices in O(1) time. However, insertion and deletion in the middle require O(n) time due to shifting elements.\n\nLinked lists store elements in nodes, each containing data and a pointer to the next node. They allow O(1) insertion and deletion at known positions but require O(n) time for access since elements must be traversed sequentially.\n\nChoosing between arrays and linked lists depends on the access patterns: arrays for random access, linked lists for frequent insertions/deletions.", contentKn = "ಸರಣಿಗಳು ಅಂಶಗಳನ್ನು ಅನುಕ್ರಮವಾಗಿ ಸಂಗ್ರಹಿಸಲಾಗುವ ಸಂಕೀರ್ಣ ಮೆಮೊರಿ ಬ್ಲಾಕ್‌ಗಳಾಗಿವೆ.", keyPointsEn = "• Array: O(1) access, O(n) insert/delete\n• Linked List: O(n) access, O(1) insert/delete\n• Singly vs Doubly linked lists\n• When to use each data structure", keyPointsKn = "• ಸರಣಿ: O(1) ಪ್ರವೇಶ\n• ಲಿಂಕ್ಡ್ ಪಟ್ಟಿ: O(n) ಪ್ರವೇಶ\n• ಏಕ ಮತ್ತು ದ್ವಿ ಲಿಂಕ್ಡ್ ಪಟ್ಟಿಗಳು", orderIndex = 1),
        Lesson(id = 7, moduleId = 3, titleEn = "Trees and Graphs", titleKn = "ಮರಗಳು ಮತ್ತು ಗ್ರಾಫ್‌ಗಳು", contentEn = "A tree is a hierarchical data structure with a root node and children. Binary Search Trees (BST) maintain ordering: left child < parent < right child, enabling O(log n) search, insert, and delete.\n\nBalanced trees like AVL and Red-Black trees ensure O(log n) height through rotations. B-trees are used in databases and file systems for efficient disk access.\n\nGraphs generalize trees by allowing cycles. They can be directed or undirected, weighted or unweighted. BFS and DFS are fundamental traversal algorithms with applications in shortest paths, connectivity, and network analysis.", contentKn = "ಮರ ಎನ್ನುವುದು ಮೂಲ ನೋಡ್ ಮತ್ತು ಮಕ್ಕಳನ್ನು ಹೊಂದಿರುವ ಶ್ರೇಣೀಕೃತ ದತ್ತಾಂಶ ರಚನೆ.", keyPointsEn = "• BST: O(log n) operations\n• AVL and Red-Black balancing\n• BFS and DFS traversals\n• Graph representations: adjacency list vs matrix", keyPointsKn = "• BST: O(log n) ಕಾರ್ಯಾಚರಣೆಗಳು\n• BFS ಮತ್ತು DFS ಅಡ್ಡಹಾಯುವಿಕೆಗಳು", orderIndex = 2),

        // Programming Fundamentals lessons
        Lesson(id = 8, moduleId = 4, titleEn = "OOP Concepts", titleKn = "ಒಒಪಿ ಪರಿಕಲ್ಪನೆಗಳು", contentEn = "Object-Oriented Programming organizes code around objects that combine data (attributes) and behavior (methods). The four pillars of OOP are encapsulation, inheritance, polymorphism, and abstraction.\n\nEncapsulation hides internal details and exposes a clean interface. Inheritance allows classes to derive from parent classes, promoting code reuse. Polymorphism enables objects to take multiple forms through method overriding and interfaces.\n\nAbstraction simplifies complex systems by modeling relevant attributes and hiding implementation details. Design patterns like Singleton, Factory, and Observer build on these OOP principles.", contentKn = "ವಸ್ತು-ಆಧಾರಿತ ಪ್ರೋಗ್ರಾಮಿಂಗ್ ಡೇಟಾ ಮತ್ತು ನಡವಳಿಕೆಯನ್ನು ಸಂಯೋಜಿಸುವ ವಸ್ತುಗಳ ಸುತ್ತ ಕೋಡ್ ಅನ್ನು ಸಂಘಟಿಸುತ್ತದೆ.", keyPointsEn = "• Four pillars: Encapsulation, Inheritance, Polymorphism, Abstraction\n• Classes, objects, and constructors\n• Method overriding vs overloading\n• SOLID principles overview", keyPointsKn = "• ನಾಲ್ಕು ಸ್ತಂಭಗಳು: ಆವರಣ, ಪರಂಪರೆ, ಬಹುರೂಪತೆ, ಅಮೂರ್ತತೆ", orderIndex = 1),
        Lesson(id = 9, moduleId = 4, titleEn = "Algorithms and Complexity", titleKn = "ಅಲ್ಗಾರಿದಮ್‌ಗಳು ಮತ್ತು ಸಂಕೀರ್ಣತೆ", contentEn = "An algorithm is a step-by-step procedure for solving a problem. Algorithm analysis uses Big-O notation to describe time and space complexity, helping compare efficiency.\n\nCommon sorting algorithms include Bubble Sort O(n²), Merge Sort O(n log n), and Quick Sort O(n log n) average. Searching algorithms range from Linear Search O(n) to Binary Search O(log n) on sorted data.\n\nUnderstanding time-space tradeoffs is crucial. Dynamic programming optimizes by storing intermediate results. Greedy algorithms make locally optimal choices for globally optimal solutions in specific problem types.", contentKn = "ಅಲ್ಗಾರಿದಮ್ ಎನ್ನುವುದು ಸಮಸ್ಯೆಯನ್ನು ಪರಿಹರಿಸುವ ಹಂತ-ಹಂತದ ಕಾರ್ಯವಿಧಾನ.", keyPointsEn = "• Big-O notation: O(1), O(log n), O(n), O(n log n), O(n²)\n• Sorting: Merge Sort, Quick Sort\n• Dynamic Programming principles\n• Greedy vs Divide-and-Conquer", keyPointsKn = "• Big-O ಸಂಕೇತ\n• ವಿಂಗಡಣೆ: ಮರ್ಜ್ ಸಾರ್ಟ್, ಕ್ವಿಕ್ ಸಾರ್ಟ್", orderIndex = 2),

        // Digital Literacy lessons
        Lesson(id = 10, moduleId = 5, titleEn = "Internet Safety and Digital Tools", titleKn = "ಇಂಟರ್ನೆಟ್ ಸುರಕ್ಷತೆ ಮತ್ತು ಡಿಜಿಟಲ್ ಸಾಧನಗಳು", contentEn = "Digital literacy encompasses the skills needed to navigate, evaluate, and create information using digital technologies. Understanding internet safety—including recognizing phishing, using strong passwords, and protecting personal data—is foundational.\n\nProductivity tools like office suites (word processing, spreadsheets, presentations), email, and cloud storage are essential for modern workplaces. Learning to use these tools effectively boosts employability.\n\nCollaboration platforms, version control basics, and professional communication through digital channels are increasingly important skills for graduates entering the workforce.", contentKn = "ಡಿಜಿಟಲ್ ಸಾಕ್ಷರತೆ ಡಿಜಿಟಲ್ ತಂತ್ರಜ್ಞಾನಗಳನ್ನು ಬಳಸಿ ಮಾಹಿತಿಯನ್ನು ನ್ಯಾವಿಗೇಟ್ ಮಾಡಲು ಅಗತ್ಯವಿರುವ ಕೌಶಲ್ಯಗಳನ್ನು ಒಳಗೊಂಡಿದೆ.", keyPointsEn = "• Password security and phishing awareness\n• Office suite proficiency\n• Cloud storage and collaboration\n• Professional digital communication", keyPointsKn = "• ಪಾಸ್‌ವರ್ಡ್ ಭದ್ರತೆ\n• ಕಚೇರಿ ಸೂಟ್ ಪ್ರಾವೀಣ್ಯ\n• ಕ್ಲೌಡ್ ಸಂಗ್ರಹಣೆ", orderIndex = 1),

        // Mechanics lessons
        Lesson(id = 11, moduleId = 6, titleEn = "Newton's Laws of Motion", titleKn = "ನ್ಯೂಟನ್‌ನ ಚಲನೆಯ ನಿಯಮಗಳು", contentEn = "Newton's First Law (Inertia): An object at rest stays at rest, and an object in motion stays in motion at constant velocity, unless acted upon by a net external force.\n\nNewton's Second Law: F = ma. The acceleration of an object is directly proportional to the net force and inversely proportional to its mass. This law is the foundation of classical mechanics.\n\nNewton's Third Law: For every action, there is an equal and opposite reaction. This principle governs interactions between objects, from rocket propulsion to walking.", contentKn = "ನ್ಯೂಟನ್‌ನ ಮೊದಲ ನಿಯಮ: ವಿಶ್ರಾಂತಿಯಲ್ಲಿರುವ ವಸ್ತು ವಿಶ್ರಾಂತಿಯಲ್ಲಿಯೇ ಇರುತ್ತದೆ.", keyPointsEn = "• First Law: Inertia\n• Second Law: F = ma\n• Third Law: Action-Reaction\n• Free body diagrams", keyPointsKn = "• ಮೊದಲ ನಿಯಮ: ಜಡತ್ವ\n• ಎರಡನೇ ನಿಯಮ: F = ma\n• ಮೂರನೇ ನಿಯಮ: ಕ್ರಿಯೆ-ಪ್ರತಿಕ್ರಿಯೆ", orderIndex = 1),
        Lesson(id = 12, moduleId = 6, titleEn = "Work, Energy and Power", titleKn = "ಕೆಲಸ, ಶಕ್ತಿ ಮತ್ತು ಸಾಮರ್ಥ್ಯ", contentEn = "Work is done when a force moves an object: W = F·d·cos(θ). The SI unit is the Joule. Work is positive when force and displacement are in the same direction.\n\nKinetic energy (½mv²) is the energy of motion, while potential energy (mgh for gravity) is stored energy. The Work-Energy Theorem states that net work equals the change in kinetic energy.\n\nPower is the rate of doing work: P = W/t. Conservation of energy states that energy cannot be created or destroyed, only transformed between forms.", contentKn = "ಬಲವು ವಸ್ತುವನ್ನು ಚಲಿಸಿದಾಗ ಕೆಲಸ ಮಾಡಲಾಗುತ್ತದೆ: W = F·d·cos(θ).", keyPointsEn = "• Work: W = F·d·cos(θ)\n• KE = ½mv², PE = mgh\n• Work-Energy Theorem\n• Conservation of Energy", keyPointsKn = "• ಕೆಲಸ: W = F·d·cos(θ)\n• KE = ½mv², PE = mgh\n• ಶಕ್ತಿ ಸಂರಕ್ಷಣೆ", orderIndex = 2),

        // Electromagnetism lessons
        Lesson(id = 13, moduleId = 7, titleEn = "Electric Fields and Forces", titleKn = "ವಿದ್ಯುತ್ ಕ್ಷೇತ್ರಗಳು ಮತ್ತು ಬಲಗಳು", contentEn = "Coulomb's Law describes the force between two charges: F = kq₁q₂/r². Like charges repel, unlike charges attract. The constant k ≈ 8.99 × 10⁹ N·m²/C².\n\nThe electric field E at a point is the force per unit charge: E = F/q. Field lines point away from positive charges and toward negative charges. The field inside a conductor is zero in electrostatic equilibrium.\n\nGauss's Law relates the electric flux through a closed surface to the enclosed charge: ΦE = Q/ε₀. It simplifies calculations for symmetric charge distributions.", contentKn = "ಕೂಲಂಬ್ ನಿಯಮ ಎರಡು ಆವೇಶಗಳ ನಡುವಿನ ಬಲವನ್ನು ವಿವರಿಸುತ್ತದೆ.", keyPointsEn = "• Coulomb's Law: F = kq₁q₂/r²\n• Electric field: E = F/q\n• Gauss's Law: ΦE = Q/ε₀\n• Conductors and insulators", keyPointsKn = "• ಕೂಲಂಬ್ ನಿಯಮ\n• ವಿದ್ಯುತ್ ಕ್ಷೇತ್ರ: E = F/q\n• ಗಾಸ್ ನಿಯಮ", orderIndex = 1),

        // Strength of Materials lessons
        Lesson(id = 14, moduleId = 8, titleEn = "Stress and Strain", titleKn = "ಒತ್ತಡ ಮತ್ತು ತಿರುಚು", contentEn = "Stress (σ) is the internal force per unit area: σ = F/A, measured in Pascals (Pa). It can be tensile (pulling apart), compressive (pushing together), or shear (sliding).\n\nStrain (ε) is the deformation per unit length: ε = ΔL/L. It is dimensionless. Hooke's Law states that stress is proportional to strain in the elastic region: σ = Eε, where E is Young's modulus.\n\nThe stress-strain curve reveals material behavior: elastic region, yield point, plastic deformation, and ultimate failure. Understanding these properties is essential for structural design.", contentKn = "ಒತ್ತಡ (σ) ಪ್ರತಿ ಘಟಕ ಪ್ರದೇಶಕ್ಕೆ ಆಂತರಿಕ ಬಲ: σ = F/A.", keyPointsEn = "• Stress: σ = F/A\n• Strain: ε = ΔL/L\n• Hooke's Law: σ = Eε\n• Stress-strain curve regions", keyPointsKn = "• ಒತ್ತಡ: σ = F/A\n• ತಿರುಚು: ε = ΔL/L\n• ಹುಕ್ ನಿಯಮ", orderIndex = 1),

        // Fluid Mechanics lessons
        Lesson(id = 15, moduleId = 9, titleEn = "Fluid Properties and Bernoulli's Principle", titleKn = "ದ್ರವ ಗುಣಲಕ್ಷಣಗಳು ಮತ್ತು ಬರ್ನೌಲಿ ತತ್ವ", contentEn = "Fluids are substances that deform continuously under shear stress. Key properties include density (ρ = m/V), viscosity (resistance to flow), and pressure (P = F/A).\n\nBernoulli's Principle states that for an ideal fluid in steady flow: P + ½ρv² + ρgh = constant. This explains why airplane wings generate lift and why a shower curtain gets pulled inward.\n\nThe continuity equation A₁v₁ = A₂v₂ ensures mass conservation in fluid flow. Reynolds number (Re = ρvD/μ) determines whether flow is laminar or turbulent.", contentKn = "ದ್ರವಗಳು ಶಿಯರ್ ಒತ್ತಡದಲ್ಲಿ ನಿರಂತರವಾಗಿ ವಿರೂಪಗೊಳ್ಳುವ ಪದಾರ್ಥಗಳಾಗಿವೆ.", keyPointsEn = "• Bernoulli's: P + ½ρv² + ρgh = const\n• Continuity: A₁v₁ = A₂v₂\n• Reynolds number and flow types\n• Viscosity and its effects", keyPointsKn = "• ಬರ್ನೌಲಿ ತತ್ವ\n• ಸಾತತ್ಯ ಸಮೀಕರಣ\n• ರೆನಾಲ್ಡ್ಸ್ ಸಂಖ್ಯೆ", orderIndex = 1)
